css:
.pv{position:relative;--fg:#171717;--fg2:#525252;--fg3:#737373;--bg:#fff;--muted:#F5F5F5;--hover:#FAFAFA;--line:#E5E5E5;--line2:#D4D4D4;--input:#737373;--inv:#171717;--invfg:#fff;
 --sh1:0 1px 2px rgba(10,13,18,.05);--sh3:0 12px 16px -4px rgba(10,13,18,.08),0 4px 6px -2px rgba(10,13,18,.03),0 0 0 1px rgba(10,13,18,.04);
 --blue:#1F4FB8;--blue-bg:#E7EFFD;--teal:#0B6B64;--teal-bg:#E2F5F4;--amber:#8A5300;--amber-bg:#FFF3DC;--green:#1B7542;--green-bg:#E8F5EC;--violet:#5536C4;--violet-bg:#EFEAFE;--gray:#404040;--gray-bg:#F0F0F0;
 --ok:#1B7542;--ok-bg:#E8F5EC;--warn:#8A5300;--warn-bg:#FFF3DC;--info:#1F4FB8;--info-bg:#E7EFFD;--logo:#0036B5;
 color:var(--fg);font:14px/20px Inter,system-ui,sans-serif;background:var(--bg)}
.pv[data-theme=dark]{--fg:#F5F5F5;--fg2:#D4D4D4;--fg3:#A3A3A3;--bg:#0A0A0A;--muted:#1F1F1F;--hover:#141414;--line:#262626;--line2:#404040;--input:#A3A3A3;--inv:#F5F5F5;--invfg:#0A0A0A;
 --sh1:none;--sh3:0 12px 24px rgba(0,0,0,.6),0 0 0 1px #262626;
 --blue:#93B9FF;--blue-bg:#0B2A6B;--teal:#8AC9C5;--teal-bg:#002F2C;--amber:#E3B87A;--amber-bg:#3F2300;--green:#93CFA6;--green-bg:#013519;--violet:#B9AAFE;--violet-bg:#250F63;--gray:#D4D4D4;--gray-bg:#262626;
 --ok:#93CFA6;--ok-bg:#013519;--warn:#E3B87A;--warn-bg:#3F2300;--info:#93B9FF;--info-bg:#051F5C;--logo:#3B6CF0}
.pv *{box-sizing:border-box}.pv button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer;text-align:left}
.pv a{color:inherit;text-decoration:none}.i{flex:none}
.mono{font-family:'JetBrains Mono',ui-monospace,monospace;font-size:13px}
.tx,.s1,.s2,.o1,.o2,.t{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hr{display:block;height:1px;background:var(--line);margin:6px 0}
.mt{display:inline-grid;place-items:center;border-radius:8px;flex:none}
.t-blue{background:var(--blue-bg);color:var(--blue)}.t-teal{background:var(--teal-bg);color:var(--teal)}.t-amber{background:var(--amber-bg);color:var(--amber)}
.t-green{background:var(--green-bg);color:var(--green)}.t-violet{background:var(--violet-bg);color:var(--violet)}.t-gray{background:var(--gray-bg);color:var(--gray)}
.lt{width:28px;height:28px;border-radius:8px;background:var(--logo);color:#fff;font:700 13px/28px Inter,system-ui,sans-serif;text-align:center;flex:none}
.ib{width:32px;height:32px;border-radius:8px;display:inline-grid;place-items:center;color:var(--fg3);position:relative;flex:none}.ib:hover{background:var(--muted)}
.nd{position:absolute;top:6px;right:7px;width:8px;height:8px;border-radius:9px;background:#D23C2E;border:2px solid var(--bg)}
.av{width:32px;height:32px;border-radius:99px;background:var(--blue-bg);color:var(--blue);display:grid;place-items:center;font:600 12px Inter,system-ui,sans-serif;flex:none}.av.lg{width:44px;height:44px;font-size:15px}
.bt{height:36px!important;padding:0 14px!important;flex:none;white-space:nowrap;border-radius:8px;border:1px solid var(--line2)!important;background:var(--bg)!important;font:600 14px Inter,system-ui,sans-serif!important;display:inline-flex;align-items:center;gap:6px;box-shadow:var(--sh1)}
.bt.pri{background:var(--inv)!important;color:var(--invfg)!important;border-color:var(--inv)!important}
.lk{font:600 13px Inter,system-ui,sans-serif!important;color:var(--fg)!important;text-decoration:underline;text-underline-offset:3px;margin-left:auto}
.chip{display:inline-block;font:500 12px/18px Inter,system-ui,sans-serif;padding:1px 8px;border-radius:999px;white-space:nowrap}.chip.ok{background:var(--ok-bg);color:var(--ok)}.chip.warn{background:var(--warn-bg);color:var(--warn)}.chip.info{background:var(--info-bg);color:var(--info)}
/* ---- web ---- */
.app{display:flex;height:800px;width:100%;position:relative;overflow:hidden;background:var(--bg)}
.rail{width:60px;flex:none;border-right:1px solid var(--line);display:flex;flex-direction:column;align-items:center;gap:6px;padding:14px 0;background:var(--hover)}
.rb{padding:2px;border-radius:10px}.rb.on{box-shadow:0 0 0 2px var(--fg)}
.sb{width:240px;flex:none;border-right:1px solid var(--line);display:flex;flex-direction:column;padding:12px;background:var(--bg);min-height:0}
.lnw{display:flex;flex-direction:column;flex:1;min-width:0}.lnb{font:12px/16px Inter,system-ui,sans-serif;color:var(--fg3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pv[data-D3=b] .sb .lg .lt{display:none}
.lg{display:flex;align-items:center;gap:8px;min-height:36px;padding:0 0 0 4px;margin-bottom:12px}.ln{font:600 14px/24px Inter,system-ui,sans-serif;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.scw{margin-bottom:12px}
.sc{display:flex;align-items:center;gap:10px;width:100%;padding:8px;border:1px solid var(--line)!important;border-radius:10px;box-shadow:var(--sh1);background:var(--bg)}.sc:hover{background:var(--hover)}
.st{display:flex;flex-direction:column;min-width:0;flex:1}.s1{font:600 14px/20px Inter,system-ui,sans-serif}.s2{font:12px/18px Inter,system-ui,sans-serif;color:var(--fg3);display:flex;min-width:0}.s2>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.s2 .dot{flex:none;padding:0 4px}.ud{color:var(--fg3);display:grid;place-items:center;flex:none}
.sc3{border:1px solid var(--line);border-radius:10px;overflow:hidden;box-shadow:var(--sh1)}
.sc3 .r{display:grid;grid-template-columns:1fr auto;grid-template-rows:auto auto;width:100%;padding:6px 10px;border-top:1px solid var(--line)}.sc3 .r:first-child{border-top:0}.sc3 .r:hover{background:var(--hover)}
.rk{font:600 11px/16px Inter,system-ui,sans-serif;color:var(--fg3);text-transform:uppercase;letter-spacing:.3px}.rv{display:flex;align-items:center;gap:6px;font:600 13px/20px Inter,system-ui,sans-serif;min-width:0;grid-column:1}.rv .i{color:var(--fg3)}
.sc3 .ud{grid-row:1/span 2;grid-column:2}
.scc{display:flex;flex-direction:column;gap:6px}.fsel{display:flex;align-items:center;gap:6px;height:32px;padding:0 10px;border:1px solid var(--line2)!important;border-radius:8px;font:500 13px Inter,system-ui,sans-serif!important;color:var(--fg2)!important;width:100%}.fsel .tx{flex:1}
.scm{display:none}
.nv{display:flex;flex-direction:column;gap:2px;overflow:auto;min-height:0;flex:1}
.gt{font:600 12px/16px Inter,system-ui,sans-serif;color:var(--fg3);text-transform:uppercase;letter-spacing:.4px;padding:16px 10px 6px}
.dv{display:block;height:1px;background:var(--line);margin:8px 10px}
.it{display:flex;align-items:center;gap:10px;height:36px;padding:0 10px;border-radius:8px;color:var(--fg2);font:500 14px/20px Inter,system-ui,sans-serif;flex:none;cursor:pointer}
.it .i{color:var(--fg3)}.it .t{flex:1}.it:hover{background:var(--hover)}
.it.par{color:var(--fg);font-weight:600;margin-top:4px}
.pv[data-D5=b] .it.ch{padding-left:40px}.pv[data-D5=b] .it.ch>.i{display:none}
.it.on{background:var(--muted);color:var(--fg);font-weight:600}.it.on .i{color:var(--fg)}
.pv[data-D6=b] .it.on{background:var(--inv);color:var(--invfg)}.pv[data-D6=b] .it.on .i{color:var(--invfg)}.pv[data-D6=b] .it.on .bd{background:transparent;color:var(--invfg);border-color:rgba(255,255,255,.35)}
.pv[data-D6=c] .it.on{background:transparent;box-shadow:inset 3px 0 0 var(--fg);border-radius:0 8px 8px 0}
.bd{font:500 12px/18px Inter,system-ui,sans-serif;padding:0 8px;border-radius:999px;background:var(--muted);border:1px solid var(--line);color:var(--fg2);flex:none}
.ft{margin-top:8px;display:flex;flex-direction:column;gap:8px;padding-top:4px}
.af{border:1px solid var(--line);border-radius:12px;padding:8px}.af1{display:flex;align-items:center;gap:10px}.af .hr{margin:8px 0}
.af2{display:flex;align-items:center;gap:6px;font:500 13px Inter,system-ui,sans-serif;color:var(--fg2);padding:0 4px}.af2 .tx{flex:1}.af2.muted{color:var(--fg3)}
.sc.bot{margin-top:0}
/* thu gọn */
:is(.pv[data-state=collapsed],.colx) .sb{width:64px;padding:12px 10px}
:is(.pv[data-state=collapsed],.colx) .ln,:is(.pv[data-state=collapsed],.colx) .lg .ib,:is(.pv[data-state=collapsed],.colx) .gt,:is(.pv[data-state=collapsed],.colx) .it .t,:is(.pv[data-state=collapsed],.colx) .it .bd,
:is(.pv[data-state=collapsed],.colx) .it.par,:is(.pv[data-state=collapsed],.colx) .scw>div,:is(.pv[data-state=collapsed],.colx) .scw>.sc,:is(.pv[data-state=collapsed],.colx) .af,:is(.pv[data-state=collapsed],.colx) .sc.bot{display:none!important}
:is(.pv[data-state=collapsed],.colx) .scm{display:grid;place-items:center;width:100%;padding:4px 0}
:is(.pv[data-state=collapsed],.colx) .lg{justify-content:center;padding:0}
:is(.pv[data-state=collapsed],.colx) .it{justify-content:center;padding:0;width:44px;margin:0 auto}:is(.pv[data-state=collapsed],.colx) .it.ch{padding:0}:is(.pv[data-state=collapsed],.colx) .it.ch>.i{display:block}
.pv[data-state=one] .ud,.pv[data-state=one] .brb .i:last-child,.pv[data-state=one] .bc .i:last-child{visibility:hidden}.pv[data-state=one] .sc,.pv[data-state=one] .sc3 .r{cursor:default;background:var(--bg)}
/* main */
.mn{flex:1;min-width:0;display:flex;flex-direction:column}
.tb{height:56px;flex:none;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;padding:0 24px}
.cr{font-size:14px;color:var(--fg3);white-space:nowrap}.cr b{color:var(--fg);font-weight:600}.sl{color:var(--line2);padding:0 2px}.sp{flex:1}
.bcs{display:flex;align-items:center;gap:2px;min-width:0}.bc{display:flex;align-items:center;gap:6px;height:32px;padding:0 8px;border-radius:8px;font:600 14px Inter,system-ui,sans-serif!important;max-width:240px}.bc:hover{background:var(--muted)}.bc .i{color:var(--fg3)}
.brb{display:flex;align-items:center;gap:6px;height:32px;padding:0 10px;border-radius:8px;font:500 14px Inter,system-ui,sans-serif!important;max-width:240px}.brb:hover{background:var(--muted)}.brb .i{color:var(--fg3)}
.tse{display:flex;align-items:center;gap:8px;width:260px;height:36px;border:1px solid var(--line2);border-radius:8px;padding:0 10px;color:var(--fg3);font-size:14px}.tse kbd{margin-left:auto;font:500 12px Inter,system-ui,sans-serif;border:1px solid var(--line);border-radius:4px;padding:0 4px}
.ct{flex:1;overflow:hidden;padding:24px;position:relative}
.ph1{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:20px}.pv h1{font:600 24px/32px Inter,system-ui,sans-serif;margin:0}.pv h2{font:600 24px/32px Inter,system-ui,sans-serif;margin:0}
.sub{margin:2px 0 0;color:var(--fg3);display:flex;gap:4px}.sub>span{white-space:nowrap}
.tbl{border:1px solid var(--line);border-radius:12px;overflow:hidden}.pv table{width:100%;border-collapse:collapse}
.pv td,.pv th{padding:12px 16px;border-bottom:1px solid var(--line);text-align:left;font-size:14px}.pv tr:last-child td{border-bottom:0}.pv th{color:var(--fg3);font:500 12px/18px Inter,system-ui,sans-serif;background:var(--hover)}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:20px}.kpi{border:1px solid var(--line);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:4px;color:var(--fg3)}.kpi b{font:600 28px/36px Inter,system-ui,sans-serif;color:var(--fg)}
.form{max-width:720px;margin:0 auto;display:flex;flex-direction:column;gap:6px}.card{border:1px solid var(--line);border-radius:12px;padding:20px;display:flex;flex-direction:column;gap:16px;margin-top:14px}
.fl{display:flex;flex-direction:column;gap:6px;font:500 14px Inter,system-ui,sans-serif;color:var(--fg2)}.in{height:40px;border:1px solid var(--line2);border-radius:8px;padding:0 12px;display:flex;align-items:center;color:var(--fg);font-weight:400}
.fa{display:flex;justify-content:flex-end;gap:12px;margin-top:16px}
.sk{display:flex;flex-direction:column;gap:12px}.sb1{background:var(--muted);border-radius:8px}
.pv[data-state=switching] .real{display:none}
/* bộ chọn */
.scrim{position:absolute;inset:0;background:rgba(10,13,18,.45);z-index:20}
.pop{position:absolute;z-index:30;background:var(--bg);border-radius:12px;box-shadow:var(--sh3);left:12px;top:104px;width:540px}
.pv[data-D1=b] .pop,.pv[data-D1=d] .pop{top:auto;bottom:84px}
.pv[data-D1=c] .pop{left:250px;top:52px}
.pv[data-D3=b] .pop{left:72px}
.pv[data-D3=b][data-D1=c] .pop{left:310px}
.pv[data-D4=b] .pop{width:320px}
.pv[data-D4=c] .pop{left:50%!important;top:50%!important;bottom:auto!important;transform:translate(-50%,-50%);width:960px}
.ph{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line);font-size:14px;min-width:0}.ph b{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.phk{display:flex;align-items:center;gap:6px;color:var(--fg3);flex:none}
.pcols{display:grid;grid-template-columns:1fr 1fr}.pcols .pc+.pc{border-left:1px solid var(--line)}
.pc{padding:8px;display:flex;flex-direction:column;gap:2px;min-width:0}
.pt{font:600 12px/18px Inter,system-ui,sans-serif;color:var(--fg3);padding:8px 8px 4px}
.op{display:flex;align-items:center;gap:10px;padding:8px;border-radius:8px;cursor:pointer;min-width:0}.op:hover{background:var(--hover)}.op.on{background:var(--muted)}
.ot{display:flex;flex-direction:column;flex:1;min-width:0}.o1{font:500 14px/20px Inter,system-ui,sans-serif}.o2{font:12px/18px Inter,system-ui,sans-serif;color:var(--fg3)}
.oi{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;color:var(--fg3);background:var(--muted);flex:none}
.ck{color:var(--fg);display:grid;place-items:center}
.rd{width:18px;height:18px;border-radius:99px;border:1.5px solid var(--line2);flex:none}.rd.on{border:5px solid var(--fg)}
.op.sel{border:1px solid var(--line);margin:0 4px}
.se{display:flex;align-items:center;gap:8px;height:32px;border:1px solid var(--input);border-radius:8px;padding:0 10px;color:var(--fg3);margin:4px 4px 6px}
.hint{font-size:13px;color:var(--fg3);padding:8px}
.nofac{display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;padding:28px 12px;color:var(--fg3)}.nofac b{color:var(--fg);font-weight:600}
.pb{padding:4px 4px 0}.pbs{max-height:520px;overflow:auto}.pb .pc{padding:0}
.pf{display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:12px 16px;border-top:1px solid var(--line);margin-top:4px}.pfh{margin-right:auto;color:var(--fg3);font-size:13px}
.mh{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--line);font:600 17px/24px Inter,system-ui,sans-serif}
.mcols{display:grid;grid-template-columns:1fr 1fr 1fr}.mcols .pc+.pc{border-left:1px solid var(--line)}
.dlg{position:absolute;z-index:30;left:50%;top:50%;transform:translate(-50%,-50%);width:420px;background:var(--bg);border-radius:12px;box-shadow:var(--sh3);padding:20px;display:flex;flex-direction:column;gap:8px}
.dlg b{font:600 18px/28px Inter,system-ui,sans-serif}.dlg p{margin:0;color:var(--fg3)}.fi{width:40px;height:40px;border-radius:99px;background:var(--warn-bg);color:var(--warn);display:grid;place-items:center;margin-bottom:8px}
/* ---- mobile ---- */
.phone{width:393px;height:800px;position:relative;overflow:hidden;display:flex;flex-direction:column;background:var(--bg);margin:0 auto}
.mst{height:44px;flex:none;display:flex;justify-content:space-between;align-items:center;padding:0 24px;font:600 15px Inter,system-ui,sans-serif}
.mh1{display:flex;align-items:center;gap:12px;padding:8px 16px}.hi{display:flex;flex-direction:column;flex:1;line-height:22px}.hi span{color:var(--fg3);font-size:14px}.hi b{font:600 18px/26px Inter,system-ui,sans-serif}
.mib{width:44px;height:44px;display:grid;place-items:center;border-radius:12px;position:relative;color:var(--fg2)}
.mib .nd{top:10px;right:11px}
.mpx{padding:4px 16px 8px}
.msc{display:flex;align-items:center;gap:12px;width:100%;padding:10px 12px;border:1px solid var(--line)!important;border-radius:14px;min-height:60px;background:var(--bg)}
.mbar{height:52px;flex:none;display:flex;align-items:center;gap:4px;padding:0 6px}.mbar b{font:600 17px/24px Inter,system-ui,sans-serif;padding-left:4px}
.mctx{display:flex;align-items:center;gap:8px;padding:0 16px 10px;font:500 13px Inter,system-ui,sans-serif;color:var(--fg2);min-width:0}.mctx .tx{display:flex}.mctx .tx>span{overflow:hidden;text-overflow:ellipsis}
.mctx.in{padding:6px 10px;margin-top:6px;border:1px solid var(--line2)!important;border-radius:999px;height:32px;max-width:100%}
.mtt{padding:0 16px 12px}
.msc-body{flex:1;overflow:hidden;position:relative}.msc-body .sk{padding:16px}
.mpad{padding:8px 16px;display:flex;flex-direction:column;gap:10px}.sect{font:600 15px/22px Inter,system-ui,sans-serif;margin-top:6px}
.sgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px 8px}.sg{display:flex;flex-direction:column;align-items:center;gap:6px;font:500 12px/16px Inter,system-ui,sans-serif;text-align:center;color:var(--fg2)}
.sgi{width:52px;height:52px;border-radius:14px;background:var(--muted);display:grid;place-items:center;color:var(--fg);position:relative}
.sgb{position:absolute;top:-4px;right:-6px;font:600 11px/18px Inter,system-ui,sans-serif;font-style:normal;background:#D23C2E;color:#fff;border-radius:99px;padding:0 6px}
.mlist{border-top:1px solid var(--line)}.mrow{display:grid;grid-template-columns:1fr auto;gap:2px 8px;padding:14px 16px;border-bottom:1px solid var(--line);align-items:center}
.mpad .mlist{border:1px solid var(--line);border-radius:14px;overflow:hidden}.mpad .mrow:last-child{border-bottom:0}
.mrow .b{font:600 15px/22px Inter,system-ui,sans-serif}.mrow .sub{grid-column:1;font-size:13px;color:var(--fg3)}.mrow>.i{grid-row:1/span 2;grid-column:2;color:var(--fg3)}
.mtabs{height:64px;flex:none;border-top:1px solid var(--line);display:grid;grid-template-columns:repeat(4,1fr);background:var(--bg)}.mtabs.five{grid-template-columns:repeat(5,1fr)}
.mtab{display:grid;place-items:center;color:var(--fg3)}.mtab.on{color:var(--fg)}
.pv[data-D7=c][data-state=open] .mtabs.five .mtab:first-child{color:var(--fg3)}.pv[data-D7=c][data-state=open] .mtabs.five .mtab:last-child{color:var(--fg)}
.mfoot{padding:12px 16px 24px;border-top:1px solid var(--line)}
.cta{width:100%;height:52px;border-radius:14px!important;background:var(--inv)!important;color:var(--invfg)!important;font:600 16px Inter,system-ui,sans-serif!important;text-align:center!important}
.mscrim{position:absolute;inset:0;background:rgba(10,13,18,.45);z-index:20}
.sheet{position:absolute;left:0;right:0;bottom:0;z-index:30;background:var(--bg);border-radius:20px 20px 0 0;max-height:86%;display:flex;flex-direction:column}
.hdl{display:block;width:36px;height:4px;border-radius:9px;background:var(--line2);margin:8px auto 0}
.shh{display:flex;justify-content:space-between;align-items:center;padding:10px 16px 6px;font:600 18px/26px Inter,system-ui,sans-serif}
.shb{overflow:hidden;padding:0 8px;flex:1}.shb .op{padding:10px 8px;min-height:48px}.op.big{min-height:52px}
.shf{padding:12px 16px 24px;border-top:1px solid var(--line)}
.drw{position:absolute;left:0;top:0;bottom:0;width:316px;z-index:30;background:var(--bg);padding:52px 12px 12px;display:flex;flex-direction:column;gap:8px;box-shadow:var(--sh3)}
.drw .lg{margin-bottom:4px}
.mnv{display:flex;flex-direction:column;overflow:hidden}.mnv .gt{padding:14px 12px 6px}
